from azure.ai.contentsafety import ContentSafetyClient

safety = ContentSafetyClient(endpoint, credential)

def screen(text: str) -> bool:
    r = safety.analyze_text(
        {"text": text},
        categories=["Hate", "SelfHarm", "Sexual", "Violence"],
    )
    return any(c.severity >= 2 for c in r.categories)

# AG-09's boundary, as a service call:
if screen(user_input):            # INPUT side
    return polite_refusal()

answer = llm_call(user_input)     # the agent work

if screen(answer):                # OUTPUT side — never skip
    return fallback_message()
return answer
